import { useState, useRef, useEffect } from "react";
import { TerminalSquare, Globe, ArrowRight } from "lucide-react";
import { isMacShortcutPlatform, shortcutLabel } from "../lib/shortcuts";

interface NewTabPopoverProps {
  open: boolean;
  onClose: () => void;
  onNewTerminal: () => void;
  onNewBrowser: (url?: string) => void;
}

export function NewTabPopover({
  open,
  onClose,
  onNewTerminal,
  onNewBrowser,
}: NewTabPopoverProps) {
  const [query, setQuery] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const isMac = isMacShortcutPlatform();

  useEffect(() => {
    if (!open) {
      setQuery("");
      return;
    }
    inputRef.current?.focus();

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        e.preventDefault();
        e.stopPropagation();
        onClose();
      }
    };

    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        onClose();
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    document.addEventListener("mousedown", handleClickOutside);

    return () => {
      window.removeEventListener("keydown", handleKeyDown);
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [open, onClose]);

  if (!open) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = query.trim();
    if (!trimmed) {
      onNewTerminal();
      onClose();
      return;
    }

    if (
      trimmed.startsWith("http://") ||
      trimmed.startsWith("https://") ||
      trimmed.startsWith("localhost") ||
      trimmed.startsWith("127.0.0.1") ||
      trimmed.includes(".")
    ) {
      let target = trimmed;
      if (!target.startsWith("http://") && !target.startsWith("https://")) {
        target = target.startsWith("localhost") || target.startsWith("127.0.0.1")
          ? `http://${target}`
          : `https://${target}`;
      }
      onNewBrowser(target);
    } else {
      onNewBrowser(`https://www.google.com/search?q=${encodeURIComponent(trimmed)}`);
    }
    onClose();
  };

  return (
    <div
      ref={containerRef}
